using System;
using System.Collections;
using System.Reflection;
using UnityEngine;
public sealed class DownInterceptTests : MonoBehaviour {
    public static bool UseAI;static bool booted;static KeyCode pressed=KeyCode.None;public static bool ReadKey(KeyCode k){return false;}public static bool ReadDown(KeyCode k){return k==pressed;}public static void Contacted(Collision2D c){}
    Component fan,zhao,manager;Type pt;Rigidbody2D ball;float scale,measured;int checks,failures;const BindingFlags IP=BindingFlags.Instance|BindingFlags.NonPublic,SP=BindingFlags.Static|BindingFlags.NonPublic;
    public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","down-test.ini");var o=new GameObject("DownInterceptTests");DontDestroyOnLoad(o);o.AddComponent<DownInterceptTests>();}
    void Check(bool ok,string text){checks++;if(!ok)failures++;Debug.Log("ABILITY "+(ok?"PASS ":"FAIL ")+text);}
    Rigidbody2D Body(Component p){return (Rigidbody2D)pt.GetField("rb").GetValue(p);}
    float Speed(Component p){float m=0,v=0;foreach(var b in p.GetComponentsInChildren<Rigidbody2D>()){m+=b.mass;v+=b.velocity.y*b.mass;}return v/Mathf.Max(.001f,m);}
    float Floor(Component p){return (float)typeof(DownIntercept).GetMethod("Floor",IP).Invoke(p.GetComponent<DownIntercept>(),null);}
    void Move(Component p,Vector2 at,float vertical=0){p.transform.position+=(Vector3)(at-Body(p).position);foreach(var r in p.GetComponentsInChildren<Rigidbody2D>()){r.velocity=Vector2.up*vertical;r.angularVelocity=0;}pt.GetField("isOnGround").SetValue(p,false);Physics2D.SyncTransforms();}
    float Error(Component p){float e=0;foreach(var j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)e=Mathf.Max(e,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return e;}
    bool Glow(Component p){if(AbilityMode.Enabled){var b=p.GetComponent<BuildPlayer>();return b!=null&&((float[])typeof(BuildPlayer).GetField("effects",IP).GetValue(b))[9]>=0;}var s=p.GetComponent<PlayerSkills>();return s!=null&&((float[])typeof(PlayerSkills).GetField("effects",IP).GetValue(s))[9]>=0;}
    IEnumerator Scene(int mode){pressed=KeyCode.None;Time.timeScale=1;UseAI=false;ControlBindings.ResetDefaults();AbilityMode.Enabled=mode==2;PlayerSkills.Enabled=mode==1;AbilityMode.Reset();if(mode==2){foreach(var b in AbilityMode.Builds){b.Levels[0]=4;b.Levels[1]=4;b.Levels[2]=0;b.Purchased=1<<9;}}
        typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.3f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;Move(fan,new Vector2(-3*scale,Body(fan).position.y));Move(zhao,new Vector2(3*scale,Body(zhao).position.y));ball.position=new Vector2(0,16);ball.gravityScale=0;ball.velocity=Vector2.zero;yield return new WaitForSeconds(.15f);GameAIMod.OnBallReset();}
    IEnumerator Passive(int mode,bool isFan){yield return Scene(mode);Component actor=isFan?fan:zhao;float floor=Floor(actor),dir=isFan?1:-1;Move(actor,Body(actor).position+Vector2.up*3*scale);ball.position=new Vector2(Body(actor).position.x+dir*1.2f*scale,floor+1*scale);ball.velocity=Vector2.right*-dir*6;ball.gravityScale=0;Physics2D.SyncTransforms();for(int i=0;i<6;i++)yield return new WaitForFixedUpdate();Check(!DownIntercept.Active(actor)&&!Glow(actor),"no-input incoming ball never starts descent mode="+mode+" actor="+actor.name);}
    IEnumerator Manual(int mode,bool isFan,bool high){yield return Scene(mode);Component actor=isFan?fan:zhao;bool skilled=mode==2||mode==1&&!isFan;float floor=Floor(actor);Move(actor,Body(actor).position+Vector2.up*3*scale,high?-2:3);ball.position=new Vector2(0,floor+(high?20:.2f)*scale);ball.velocity=Vector2.zero;ball.gravityScale=0;Physics2D.SyncTransforms();pressed=ControlBindings.Get(isFan,GameControlAction.Down);yield return null;yield return null;pressed=KeyCode.None;bool active=DownIntercept.Active(actor);for(int i=0;i<8;i++)yield return new WaitForFixedUpdate();float y=Speed(actor);Check(active&&y<-.3f&&Error(actor)<.6f&&(!skilled||Glow(actor)),"manual descent ignores "+(high?"high":"low")+" ball, cancels ascent when needed mode="+mode+" actor="+actor.name+" v="+y);}
    IEnumerator Measure(int mode,bool isFan,bool input){yield return Scene(mode);Component actor=isFan?fan:zhao;Move(actor,Body(actor).position+Vector2.up*4.4f*scale,-2);float began=Time.fixedTime;pressed=input?ControlBindings.Get(isFan,GameControlAction.Down):KeyCode.None;yield return null;yield return null;while(Time.fixedTime-began<9f*Time.fixedDeltaTime-.001f)yield return new WaitForFixedUpdate();pressed=KeyCode.None;measured=-Speed(actor);}
    IEnumerator Ratios(bool isFan){yield return Measure(0,isFan,false);float normal=measured;yield return Measure(0,isFan,true);float basic=measured;yield return Measure(2,isFan,true);float paid=measured;yield return Measure(1,isFan,true);float native=measured;Check(normal>1&&Mathf.Abs(basic/normal-3f)<.2f&&Mathf.Abs(paid/normal-6f)<.3f&&Mathf.Abs(native/normal-(isFan?3f:6f))<.3f,"real rig paired free-fall ratios "+(isFan?"Fan":"Zhao")+" normal="+normal+" basic="+basic/normal+" paid="+paid/normal+" native="+native/normal);}
    IEnumerator Landing(bool isFan){yield return Scene(isFan?2:0);Component actor=isFan?fan:zhao;var rig=actor.GetComponentsInChildren<Rigidbody2D>();var modes=new CollisionDetectionMode2D[rig.Length];for(int i=0;i<rig.Length;i++)modes[i]=rig[i].collisionDetectionMode;Move(actor,Body(actor).position+Vector2.up*3*scale,-2);pressed=ControlBindings.Get(isFan,GameControlAction.Down);float error=0;bool launched=false;for(int i=0;i<110;i++){yield return new WaitForFixedUpdate();if(i==3)pressed=KeyCode.None;launched|=DownIntercept.Active(actor);error=Mathf.Max(error,Error(actor));}bool restored=true;for(int i=0;i<rig.Length;i++)restored&=rig[i].collisionDetectionMode==modes[i];Check(launched&&!DownIntercept.Active(actor)&&restored&&error<.6f&&Mathf.Abs(Mathf.DeltaAngle(Body(actor).rotation,0))<45,"real landing ends boost, restores collision modes and keeps balance "+actor.name+" joints="+error);}
    IEnumerator Guards(){yield return Scene(2);Move(fan,Body(fan).position+Vector2.up*3*scale,2);ControlBindings.Set(true,GameControlAction.Down,KeyCode.F);pressed=KeyCode.F;yield return null;yield return null;pressed=KeyCode.None;for(int i=0;i<6;i++)yield return new WaitForFixedUpdate();Check(DownIntercept.Active(fan)&&Speed(fan)<0&&Glow(fan),"remapped down starts 6x descent at zero jump points");DownIntercept.ResetAll();Time.timeScale=0;pressed=KeyCode.F;yield return null;yield return null;bool paused=!DownIntercept.Active(fan);Time.timeScale=1;pressed=KeyCode.None;yield return Scene(0);pressed=ControlBindings.Get(true,GameControlAction.Down);yield return null;yield return null;pressed=KeyCode.None;Check(paused&&!DownIntercept.Active(fan),"pause/reset clear descent and grounded input cannot force through pitch");}
    IEnumerator Start(){Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=120;AudioListener.volume=0;yield return new WaitForSeconds(.2f);for(int mode=0;mode<3;mode++)foreach(bool actor in new bool[]{true,false}){yield return Passive(mode,actor);yield return Manual(mode,actor,false);yield return Manual(mode,actor,true);}yield return Ratios(true);yield return Ratios(false);yield return Landing(true);yield return Landing(false);yield return Guards();Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
    void Update(){if(Time.realtimeSinceStartup>120){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
}